normalize.source:
function normalize(){
  const vals=DIM_KEYS.map(k=>scores[k]), mn=Math.min(...vals), mx=Math.max(...vals), o={};
  DIM_KEYS.forEach(k=>o[k]=Math.round(mx===mn?60:28+(scores[k]-mn)/(mx-mn)*66));
  return o;
}

similarity.source:
function similarity(u,p){
  const arr=DIM_KEYS.map(k=>u[k]);
  const dist=Math.sqrt(arr.reduce((s,x,i)=>s+(x-p.v[i])**2,0)/6);
  return Math.max(52,Math.min(97,100-dist*.72));
}
